        // so writes do not block while the browser is alive; a dead browser
        // gives EPIPE (SIGPIPE is ignored by Rust's runtime). A browser that
        // is alive but stuck is killed by the replay watchdog.
        self.tx
            .write_all(&bytes)
            .map_err(|e| anyhow!("CDP write failed ({method}): {e}"))?;
