    /// an id in `first..=last` is an error. Returns `last`'s result.
    fn wait_ids(&mut self, first: u64, last: u64, method: &str, deadline: Instant) -> Result<Value> {
        loop {
            if self.killed.load(Ordering::SeqCst) {
                bail!("VS Code was stopped during {method}");
