const BATCH: usize = 48;

fn replay_actions(cdp: &mut Cdp, actions: &[Action], deadline: Instant) -> Result<()> {
    let mut batch: Vec<(&'static str, Value)> = Vec::with_capacity(BATCH + 8);
    for action in actions {
