        text: None,
        modifiers: MOD_CTRL | MOD_ALT | MOD_SHIFT,
    }
}

fn send_key(cdp: &mut Cdp, k: &CdpKey, deadline: Instant) -> Result<()> {
    cdp.pipeline(key_events(k).into(), deadline)
}

